using System;using System.IO;using System.Drawing;using System.Reflection;using System.Windows.Forms;
namespace FleetLab
{
    internal static class PracticeGoalRouteFormChecks
    {
        static void Need(bool ok,string s){if(!ok)throw new InvalidDataException(s);}static T Find<T>(Form f,string name) where T:Control{return (T)f.Controls.Find(name,true)[0];}
        static void Show(Form f,Form owner){f.ShowInTaskbar=false;f.StartPosition=FormStartPosition.Manual;f.Location=new Point(-20000,-20000);f.Show(owner);Application.DoEvents();}
        static void Load(Form f,int preset){Find<ComboBox>(f,"goalRouteProfile").SelectedIndex=preset;Find<Button>(f,"goalRouteLoad").PerformClick();}
        static void Key(Form f,bool down,Keys key){typeof(Control).GetMethod(down?"OnKeyDown":"OnKeyUp",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(f,new object[]{new KeyEventArgs(key)});}
        internal static void Run(Action<string,Action> check,string assets,Form owner)
        {
            string programs=Path.Combine(Path.GetDirectoryName(assets),"Programs");var source=File.ReadAllBytes(Path.Combine(assets,"Graphics","BSSB202.SCN"));Func<PracticeMapStartup> startup=delegate{return PracticeMapStartup.CreateBssb202(programs,source,731);};
            check("Route costs form builds a partial original grid and selects numeric cells without moving the fleet",delegate{
                using(var f=new PracticeGoalRouteStudy(programs,startup())){Show(f,owner);Need(f.StudyState.Visits==0&&Find<Button>(f,"goalRouteBuild").Enabled&&!Find<Button>(f,"goalRouteRetry").Enabled,"Prepared controls");Find<Button>(f,"goalRouteBuild").PerformClick();Need(f.StudyState.Result.Outcome==PracticeGoalRouteOutcome.RouteFound&&!Find<Button>(f,"goalRouteBuild").Enabled&&f.StudyState.OriginX==100&&f.StudyState.OriginY==100&&Find<Label>(f,"goalRouteFeedback").Text.Contains("no fleet moved"),"Build feedback");f.SelectCell(13,12);Need(Find<Label>(f,"goalRouteCell").Text.Contains("Byte 1 (0x01)")&&Find<TextBox>(f,"goalRouteDetails").ReadOnly,"Cell selection");Find<Button>(f,"goalRouteBuild").PerformClick();Need(f.StudyState.Visits==1,"Repeated build");f.Close();}
            });
            check("Route costs form exposes explicit retry cache paths and keeps pending preset separate from reset",delegate{
                using(var f=new PracticeGoalRouteStudy(programs,startup())){Show(f,owner);Load(f,2);Find<Button>(f,"goalRouteBuild").PerformClick();Need(f.StudyState.CanRetry&&Find<Button>(f,"goalRouteChanged").Enabled,"Failed retry controls");Find<Button>(f,"goalRouteRetry").PerformClick();Need(f.StudyState.Result.Outcome==PracticeGoalRouteOutcome.NeighborhoodHeld&&f.StudyState.SourceClock==14345&&!Find<Button>(f,"goalRouteChanged").Enabled,"Same blockers retry");Find<ComboBox>(f,"goalRouteProfile").SelectedIndex=3;Find<Button>(f,"goalRouteReset").PerformClick();Need(f.StudyState.Preset==2&&f.StudyState.Visits==0,"Pending reset changed applied preset");Find<Button>(f,"goalRouteBuild").PerformClick();Find<Button>(f,"goalRouteChanged").PerformClick();Need(f.StudyState.Result.Outcome==PracticeGoalRouteOutcome.RouteUnavailable&&f.StudyState.Visits==2,"Changed blocker retry");Find<Button>(f,"goalRouteLoad").PerformClick();Find<Button>(f,"goalRouteBuild").PerformClick();Need(f.StudyState.Preset==3&&f.StudyState.Result.Outcome==PracticeGoalRouteOutcome.CooldownHeld&&Find<Label>(f,"goalRouteFeedback").Text.Contains("after clearing"),"Loaded cooldown");f.Close();}
            });
            check("Route costs form suppresses held confirmation and keeps minimum-size controls reachable on unsupported copies",delegate{
                using(var f=new PracticeGoalRouteStudy(programs,startup())){Show(f,owner);Find<Button>(f,"goalRouteBuild").PerformClick();f.ActiveControl=Find<Button>(f,"goalRouteReset");Key(f,true,Keys.Enter);var first=f.StudyState;Key(f,true,Keys.Enter);Need(Object.ReferenceEquals(first,f.StudyState)&&first.Visits==0,"Held repeat reset");Key(f,false,Keys.Enter);Key(f,true,Keys.Enter);Need(!Object.ReferenceEquals(first,f.StudyState),"Released confirmation lost");Key(f,false,Keys.Enter);f.Size=f.MinimumSize;Application.DoEvents();var scroll=Find<Panel>(f,"goalRouteScroll");var close=Find<Button>(f,"goalRouteClose");scroll.ScrollControlIntoView(close);Application.DoEvents();var box=scroll.RectangleToClient(close.RectangleToScreen(close.ClientRectangle));Need(scroll.AutoScroll&&Find<Control>(f,"goalRouteCanvas").Width>480&&box.Bottom<=scroll.ClientSize.Height+2,"Minimum layout/close");f.Close();}
                using(var f=new PracticeGoalRouteStudy(programs,PracticeMapStartup.CreateBssb202(programs,source,732))){Show(f,owner);Need(f.StudyState==null&&!Find<Button>(f,"goalRouteLoad").Enabled&&!Find<Button>(f,"goalRouteBuild").Enabled&&!Find<Button>(f,"goalRouteRetry").Enabled&&Find<Label>(f,"goalRouteFeedback").Text.Contains("seed731"),"Unsupported basis enabled");Find<Button>(f,"goalRouteClose").PerformClick();Need(f.IsDisposed,"Unsupported copy not closable");}
            });
            check("Recovered maps opens route costs directly and preserves the active battle",delegate{
                var main=owner as MainForm;Need(main!=null,"Main form required");var tabs=(TabControl)typeof(MainForm).GetField("tabs",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(main);int previous=tabs.SelectedIndex,maps=-1;for(int n=0;n<tabs.TabPages.Count;n++)if(tabs.TabPages[n].Text=="Recovered maps")maps=n;Need(maps>=0,"Maps tab");tabs.SelectedIndex=maps;Application.DoEvents();var battle=main.State;int events=battle.Events.Count;bool saw=false;Exception error=null;
                using(var timer=new Timer{Interval=100}){timer.Tick+=delegate{foreach(Form child in main.OwnedForms){var f=child as PracticeGoalRouteStudy;if(f==null)continue;timer.Stop();try{Find<Button>(f,"goalRouteBuild").PerformClick();Need(f.StudyState.Result.Outcome==PracticeGoalRouteOutcome.RouteFound,"Direct cost search");saw=true;}catch(Exception e){error=e;}finally{f.Close();}return;}};timer.Start();Find<Button>(main,"openGoalRouteStudy").PerformClick();timer.Stop();}tabs.SelectedIndex=previous;if(error!=null)throw error;Need(saw&&Object.ReferenceEquals(battle,main.State)&&battle.Events.Count==events,"Study entry changed battle");
            });
        }
        internal static int SavePreviews(string assets,string destination)
        {
            destination=Path.GetFullPath(destination);if(Directory.Exists(destination)||File.Exists(destination))throw new IOException("Choose a fresh route-cost preview directory.");Directory.CreateDirectory(destination);string programs=Path.Combine(Path.GetDirectoryName(assets),"Programs");var startup=PracticeMapStartup.CreateBssb202(programs,File.ReadAllBytes(Path.Combine(assets,"Graphics","BSSB202.SCN")),731);
            using(var f=new PracticeGoalRouteStudy(programs,startup)){Show(f,null);Action<string> capture=delegate(string name){f.PerformLayout();Application.DoEvents();using(var b=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(b,new Rectangle(Point.Empty,f.Size));b.Save(Path.Combine(destination,name+".png"),System.Drawing.Imaging.ImageFormat.Png);}};capture("01-Prepared");Find<Button>(f,"goalRouteBuild").PerformClick();capture("02-Costs");Load(f,1);Find<Button>(f,"goalRouteBuild").PerformClick();capture("03-Barrier");Load(f,2);Find<Button>(f,"goalRouteBuild").PerformClick();capture("04-Failed");Find<Button>(f,"goalRouteRetry").PerformClick();capture("05-Cache-Held");Find<Button>(f,"goalRouteReset").PerformClick();Find<Button>(f,"goalRouteBuild").PerformClick();Find<Button>(f,"goalRouteChanged").PerformClick();capture("06-Changed-Cache");Load(f,3);Find<Button>(f,"goalRouteBuild").PerformClick();capture("07-Cooldown");Load(f,4);Find<Button>(f,"goalRouteBuild").PerformClick();capture("08-Quartet");f.Size=f.MinimumSize;capture("09-Minimum");Find<Panel>(f,"goalRouteScroll").ScrollControlIntoView(Find<TextBox>(f,"goalRouteDetails"));capture("10-Minimum-Details");f.Close();}
            File.WriteAllText(Path.Combine(destination,"Scope.txt"),"Ten actual-form route-cost previews:prepared,costs,barrier,failure,cachehold,changedcache,cooldown,quartet,minimum,minimumdetails. Modern schematic colors/fixedmarkers;actual recovered cost bytes. No goal4following/fleetmovement/worldpacing/audio/battle/settings changes. Physical scaling/input remains a hands-on check.\r\n");return 0;
        }
    }
